import {
  areaY,
  barX,
  barY,
  type ChartPositionScaleOptions,
  crosshair,
  defineChart,
  dot,
  group,
  lineY,
  stack,
  stackRowsY,
} from "@tanstack/charts";
import { decorative } from "@tanstack/charts/mark/decorative";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { tooltip as pointerTooltip } from "@tanstack/charts/tooltip";
import { type ChartColor, chartColor, chartSeriesColor } from "@/components/control-ui/ui/chart-colors";
import { type ChartCurveName, chartCurve } from "@/components/control-ui/ui/chart-curves";
import {
  type ChartPart,
  type ChartReference,
  chartBarFill,
  chartBarGradients,
  chartBars,
  chartFillPaint,
  chartGradients,
  chartOutline,
  chartPart,
  chartReferenceMarks,
  dimUnfocused,
  quietAxis,
  quietGrid,
  seriesTooltip,
} from "@/components/control-ui/ui/chart-marks";
import {
  type ChartFill,
  type ChartSeries,
  type ChartValueKey,
  type ChartXKey,
  type ChartXValue,
  chartFormatters,
  chartSeriesRows,
  chartXScale,
  type ResolvedChartSeries,
  resolveChartSeries,
} from "@/components/control-ui/ui/chart-series";

export type CartesianChartOptions<TDatum> = {
  data: readonly TDatum[];
  x: ChartXKey<TDatum>;
  series: readonly ChartSeries<TDatum>[];
  fill?: ChartFill;
  xScale?: Partial<ChartPositionScaleOptions>;
  yScale?: Partial<ChartPositionScaleOptions>;
  formatX?: (value: ChartXValue) => string;
  formatValue?: (value: number) => string;
  formatTick?: (value: number) => string;
  locale?: Intl.LocalesArgument;
  references?: readonly ChartReference[];
  grid?: boolean;
  tooltip?: boolean;
};

export type AreaChartOptions<TDatum> = CartesianChartOptions<TDatum> & {
  stacked?: boolean | "percent";
  curve?: ChartCurveName;
};

export type LineChartOptions<TDatum> = CartesianChartOptions<TDatum> & {
  curve?: ChartCurveName;
  dots?: boolean;
};

export type BarChartOptions<TDatum> = CartesianChartOptions<TDatum> & {
  orientation?: "vertical" | "horizontal";
  layout?: "grouped" | "stacked" | "percent";
};

function cartesianSetup<TDatum>(options: CartesianChartOptions<TDatum>, percent: boolean) {
  const series = resolveChartSeries(options.series, options.fill ?? "gradient");
  const rows = chartSeriesRows(options.data, options.x, series);
  const formats = chartFormatters(options.locale);
  const formatX = options.formatX ?? formats.x;
  const formatValue = options.formatValue ?? formats.value;
  const valueScale = {
    scale: scaleLinear,
    nice: true,
    grid: options.grid === false ? false : quietGrid,
    axis: quietAxis(options.formatTick ?? (percent ? formats.percent : formats.tick)),
    ...options.yScale,
  };
  return {
    series,
    rows,
    formatX,
    valueScale,
    tooltip:
      options.tooltip === false
        ? (false as const)
        : seriesTooltip(
            series.map((entry) => entry.label),
            formatX,
            formatValue,
          ),
    lastX: rows.at(-1)?.x,
  };
}

function gradientColors<TDatum>(series: readonly ResolvedChartSeries<TDatum>[]): ChartColor[] {
  return series.filter((entry) => entry.fill === "gradient").map((entry) => entry.color);
}

const SERIES_FOCUS_POINT = { id: "focus", key: "id", x: "x", z: "series", r: 4, fillOpacity: 0, strokeOpacity: 0 } as const;

export function areaChart<TDatum>(options: AreaChartOptions<TDatum>) {
  const stacked = options.stacked ?? false;
  const { series, rows, formatX, valueScale, tooltip, lastX } = cartesianSetup(options, stacked === "percent");
  const curve = chartCurve(options.curve ?? "smooth");
  const stackedRows = stacked
    ? stackRowsY(rows, { x: "x", y: "value", z: "series", offset: stacked === "percent" ? "normalize" : undefined })
    : [];
  const seriesMarks = series.flatMap((entry) => {
    const areaParts: ChartPart[] = entry.fill === "hatched" ? ["area", "area-hatched"] : ["area"];
    const fill = chartFillPaint(entry.color, entry.fill, "area");
    const line = {
      id: `line-${entry.key}`,
      key: "id",
      x: "x",
      stroke: chartColor(entry.color),
      strokeDasharray: entry.dashed ? "4 4" : undefined,
      curve,
    } as const;
    if (stacked) {
      const seriesRows = stackedRows.filter((row) => row.series === entry.label);
      return [
        decorative(
          chartPart(areaY(seriesRows, { id: `area-${entry.key}`, key: "id", x: "x", y1: "y1", y2: "y2", fill, curve }), ...areaParts),
        ),
        decorative(chartPart(lineY(seriesRows, { ...line, y: "y2" }), "line")),
      ];
    }
    const seriesRows = rows.filter((row) => row.series === entry.label);
    return [
      decorative(chartPart(areaY(seriesRows, { id: `area-${entry.key}`, key: "id", x: "x", y: "value", fill, curve }), ...areaParts)),
      decorative(chartPart(lineY(seriesRows, { ...line, y: "value" }), "line")),
    ];
  });
  const focusPoints = stacked ? dot(stackedRows, { ...SERIES_FOCUS_POINT, y: "y2" }) : dot(rows, { ...SERIES_FOCUS_POINT, y: "value" });
  return defineChart({
    marks: [
      ...seriesMarks,
      ...chartReferenceMarks(options.references ?? [], "y", lastX),
      focusPoints,
      crosshair({ x: true, y: false, strokeDasharray: "3 3" }),
    ],
    scales: {
      x: { ...chartXScale(rows, "point", options.xScale), axis: quietAxis(formatX) },
      y: valueScale,
    },
    gradients: chartGradients(gradientColors(series), "area"),
    margin: { top: 8 },
    focus: "group-x",
    maxFocusDistance: Number.POSITIVE_INFINITY,
    tooltip,
  });
}

export function lineChart<TDatum>(options: LineChartOptions<TDatum>) {
  const { series, rows, formatX, valueScale, tooltip, lastX } = cartesianSetup(options, false);
  const curve = chartCurve(options.curve ?? "smooth");
  const seriesMarks = series.flatMap((entry) => {
    const seriesRows = rows.filter((row) => row.series === entry.label);
    const line = decorative(
      chartPart(
        lineY(seriesRows, {
          id: `line-${entry.key}`,
          key: "id",
          x: "x",
          y: "value",
          stroke: chartColor(entry.color),
          strokeDasharray: entry.dashed ? "4 4" : undefined,
          curve,
        }),
        "line",
      ),
    );
    if (!options.dots) return [line];
    const dots = decorative(
      chartPart(
        dot(seriesRows, {
          id: `dot-${entry.key}`,
          key: "id",
          x: "x",
          y: "value",
          r: 3,
          fill: chartColor(entry.color),
          stroke: "var(--cui-chart-background)",
          strokeWidth: 1.5,
        }),
        "dot",
      ),
    );
    return [line, dots];
  });
  return defineChart({
    marks: [
      ...seriesMarks,
      ...chartReferenceMarks(options.references ?? [], "y", lastX),
      dot(rows, { ...SERIES_FOCUS_POINT, y: "value" }),
      crosshair({ x: true, y: false, strokeDasharray: "3 3" }),
    ],
    scales: {
      x: { ...chartXScale(rows, "point", options.xScale), axis: quietAxis(formatX) },
      y: valueScale,
    },
    margin: { top: 8 },
    focus: "group-x",
    maxFocusDistance: Number.POSITIVE_INFINITY,
    tooltip,
  });
}

export function barChart<TDatum>(options: BarChartOptions<TDatum>) {
  const layoutName = options.layout ?? "grouped";
  const { rows, formatX, valueScale, tooltip } = cartesianSetup(options, layoutName === "percent");
  const barLayouts = { grouped: group({ padding: 0.15 }), stacked: undefined, percent: stack({ offset: "normalize" }) };
  const layout = barLayouts[layoutName];
  const categoryScale = { ...chartXScale(rows, "band", options.xScale), axis: quietAxis(formatX) };
  const band = { inset: -4, radius: 6, fillOpacity: 0.06 };
  const shared = {
    id: "bars",
    key: "id",
    z: "series",
    stroke: (row: (typeof rows)[number]) => chartOutline(row.color, row.fill),
    strokeWidth: 1,
    radius: { end: 6 },
    states: dimUnfocused,
    layout,
  } as const;

  if (options.orientation === "horizontal") {
    return defineChart({
      marks: [
        crosshair({ x: false, y: { band } }),
        chartBars(barX(rows, { ...shared, y: "x", x: "value", fill: (row) => chartBarFill(row, "x") }), "x"),
        ...chartReferenceMarks(options.references ?? [], "x", rows[0]?.x),
      ],
      scales: { x: valueScale, y: categoryScale },
      gradients: chartBarGradients(rows, "x"),
      margin: { top: 8 },
      focus: "group-y",
      maxFocusDistance: Number.POSITIVE_INFINITY,
      tooltip,
    });
  }

  return defineChart({
    marks: [
      crosshair({ x: { band }, y: false }),
      chartBars(barY(rows, { ...shared, x: "x", y: "value", fill: (row) => chartBarFill(row, "y") }), "y"),
      ...chartReferenceMarks(options.references ?? [], "y", rows.at(-1)?.x),
    ],
    scales: { x: categoryScale, y: valueScale },
    gradients: chartBarGradients(rows, "y"),
    margin: { top: 8 },
    focus: "group-x",
    maxFocusDistance: Number.POSITIVE_INFINITY,
    tooltip,
  });
}

export type ScatterChartOptions<TDatum> = {
  data: readonly TDatum[];
  x: ChartValueKey<TDatum>;
  y: ChartValueKey<TDatum>;
  size?: ChartValueKey<TDatum>;
  group?: ChartXKey<TDatum>;
  colors?: Partial<Record<string, ChartColor>>;
  xLabel?: string;
  yLabel?: string;
  formatX?: (value: number) => string;
  formatValue?: (value: number) => string;
  locale?: Intl.LocalesArgument;
  xScale?: Partial<ChartPositionScaleOptions>;
  yScale?: Partial<ChartPositionScaleOptions>;
  references?: readonly ChartReference[];
};

type ScatterRow = { id: string; x: number; y: number; size: number; group: string };

function finiteNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function scatterRows<TDatum>(options: ScatterChartOptions<TDatum>): ScatterRow[] {
  return options.data.flatMap((datum, index) => {
    const x = finiteNumber(datum[options.x]);
    const y = finiteNumber(datum[options.y]);
    if (x === undefined || y === undefined) return [];
    const size = options.size === undefined ? 0 : (finiteNumber(datum[options.size]) ?? 0);
    const groupValue: unknown = options.group ? datum[options.group] : "";
    const groupName = groupValue instanceof Date ? groupValue.toISOString() : String(groupValue ?? "");
    return { id: String(index), x, y, size, group: groupName };
  });
}

export function scatterChart<TDatum>(options: ScatterChartOptions<TDatum>) {
  const rows = scatterRows(options);
  const groups = [...new Set(rows.map((row) => row.group))];
  const maxSize = Math.max(1, ...rows.map((row) => row.size));
  const formats = chartFormatters(options.locale);
  const formatX = options.formatX ?? formats.value;
  const formatValue = options.formatValue ?? formats.value;
  const xLabel = options.xLabel ?? options.x;
  const yLabel = options.yLabel ?? options.y;
  const sizeKey = options.size;
  const radius = sizeKey ? (row: ScatterRow) => 3 + 11 * Math.sqrt(row.size / maxSize) : 4;
  const dots = groups.map((groupName, groupIndex) => {
    const color = chartColor(options.colors?.[groupName] ?? chartSeriesColor(groupIndex));
    return chartPart(
      dot(
        rows.filter((row) => row.group === groupName),
        {
          id: `dot-${groupName}`,
          key: "id",
          x: "x",
          y: "y",
          r: radius,
          fill: color,
          fillOpacity: 0.65,
          stroke: color,
          strokeWidth: 1,
          states: dimUnfocused,
        },
      ),
      "dot",
    );
  });
  const rightmostX = rows.length > 0 ? Math.max(...rows.map((row) => row.x)) : undefined;
  return defineChart({
    marks: [...dots, ...chartReferenceMarks(options.references ?? [], "y", rightmostX)],
    scales: {
      x: { scale: scaleLinear, nice: true, grid: quietGrid, axis: quietAxis(formats.tick), ...options.xScale },
      y: { scale: scaleLinear, nice: true, grid: quietGrid, axis: quietAxis(formats.tick), ...options.yScale },
    },
    margin: { top: 8 },
    focus: "nearest",
    tooltip: {
      use: pointerTooltip,
      content: (points) => {
        const point = points[0]?.datum;
        if (!point) return { rows: [] };
        const color = chartColor(options.colors?.[point.group] ?? chartSeriesColor(groups.indexOf(point.group)));
        return {
          title: point.group || undefined,
          rows: [
            { label: xLabel, value: formatX(point.x), color },
            { label: yLabel, value: formatValue(point.y), color },
            ...(sizeKey ? [{ label: sizeKey, value: formatValue(point.size), color }] : []),
          ],
        };
      },
    },
  });
}

export type SparklineChartOptions<TDatum> = {
  data: readonly TDatum[];
  x: ChartXKey<TDatum>;
  y: ChartValueKey<TDatum>;
  color?: ChartColor;
  fill?: ChartFill;
  type?: "area" | "line" | "bar";
  curve?: ChartCurveName;
  xScale?: Partial<ChartPositionScaleOptions>;
};

export function sparklineChart<TDatum>(options: SparklineChartOptions<TDatum>) {
  const color = options.color ?? "blue";
  const fill = options.fill ?? "gradient";
  const type = options.type ?? "area";
  const curve = chartCurve(options.curve ?? "smooth");
  const rows = chartSeriesRows(options.data, options.x, resolveChartSeries([{ key: options.y, color, fill }]));
  const values = rows.flatMap((row) => (row.value === null ? [] : row.value));
  const min = values.length > 0 ? Math.min(...values) : 0;
  const shared = {
    guides: false,
    margin: 2,
    focus: false,
    pointer: false,
    keyboard: false,
    tooltip: false,
  } as const;
  const valueScale = { scale: scaleLinear, nice: false };

  if (type === "bar") {
    return defineChart({
      ...shared,
      marks: [chartBars(barY(rows, { key: "id", x: "x", y: "value", fill: (row) => chartBarFill(row, "y"), radius: { end: 2 } }), "y")],
      scales: { x: { scale: () => scaleBand().padding(0.2), ...options.xScale }, y: valueScale },
      gradients: chartBarGradients(rows, "y"),
    });
  }

  const line = chartPart(lineY(rows, { key: "id", x: "x", y: "value", stroke: chartColor(color), curve }), "line");
  const areaParts: ChartPart[] = fill === "hatched" ? ["area", "area-hatched"] : ["area"];
  const area = chartPart(
    areaY(rows, { key: "id", x: "x", y1: min, y2: "value", fill: chartFillPaint(color, fill, "area"), curve }),
    ...areaParts,
  );
  return defineChart({
    ...shared,
    marks: type === "area" ? [area, line] : [line],
    scales: { x: chartXScale(rows, "point", options.xScale), y: valueScale },
    gradients: type === "area" && fill === "gradient" ? chartGradients([color], "area") : [],
  });
}

export const CHART_COLORS = ["blue", "purple", "pink", "orange", "green", "yellow", "red", "neutral"] as const;

export type ChartColor = (typeof CHART_COLORS)[number];

export const CHART_SERIES_COLORS = ["blue", "purple", "pink", "orange", "green", "yellow"] as const satisfies readonly ChartColor[];

export function chartColor(color: ChartColor) {
  return `var(--chart-${color})`;
}

export function chartSeriesColor(index: number): ChartColor {
  return CHART_SERIES_COLORS[index % CHART_SERIES_COLORS.length] ?? "blue";
}

import type { ChartCurve } from "@tanstack/charts";

type Point = readonly [number, number];

export type ChartCurveName = "smooth" | "linear" | "step";

function monotoneTangents(points: readonly Point[]): number[] {
  const tangents = points.map(() => 0);
  const last = points.length - 1;
  for (let index = 1; index < last; index += 1) {
    const [x0, y0] = points[index - 1] ?? [0, 0];
    const [x1, y1] = points[index] ?? [0, 0];
    const [x2, y2] = points[index + 1] ?? [0, 0];
    const h0 = x1 - x0;
    const h1 = x2 - x1;
    const s0 = h0 ? (y1 - y0) / h0 : 0;
    const s1 = h1 ? (y2 - y1) / h1 : 0;
    const weightedSlope = (s0 * h1 + s1 * h0) / (h0 + h1);
    tangents[index] = (Math.sign(s0) + Math.sign(s1)) * Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(weightedSlope)) || 0;
  }
  if (last > 0) {
    tangents[0] = endTangent(points[0], points[1], tangents[1] ?? 0);
    tangents[last] = endTangent(points[last - 1], points[last], tangents[last - 1] ?? 0);
  }
  return tangents;
}

function endTangent(from: Point | undefined, to: Point | undefined, neighbourTangent: number): number {
  if (!(from && to)) return neighbourTangent;
  const h = to[0] - from[0];
  return h ? ((3 * (to[1] - from[1])) / h - neighbourTangent) / 2 : neighbourTangent;
}

function monotoneSegments(points: readonly Point[]): string[] {
  if (points.length < 3) return points.slice(1).map(([x, y]) => `L${x},${y}`);
  const tangents = monotoneTangents(points);
  return points.slice(1).map(([x1, y1], index) => {
    const [x0, y0] = points[index] ?? [x1, y1];
    const t0 = tangents[index] ?? 0;
    const t1 = tangents[index + 1] ?? 0;
    const dx = (x1 - x0) / 3;
    return `C${x0 + dx},${y0 + dx * t0} ${x1 - dx},${y1 - dx * t1} ${x1},${y1}`;
  });
}

function reversedMonotoneSegments(points: readonly Point[]): string[] {
  if (points.length < 3)
    return points
      .slice(0, -1)
      .map(([x, y]) => `L${x},${y}`)
      .reverse();
  const tangents = monotoneTangents(points);
  return points
    .slice(1)
    .map(([x1, y1], index) => {
      const [x0, y0] = points[index] ?? [x1, y1];
      const t0 = tangents[index] ?? 0;
      const t1 = tangents[index + 1] ?? 0;
      const dx = (x1 - x0) / 3;
      return `C${x1 - dx},${y1 - dx * t1} ${x0 + dx},${y0 + dx * t0} ${x0},${y0}`;
    })
    .reverse();
}

function closedArea(top: readonly Point[], bottom: readonly Point[], topSegments: string[], bottomSegments: string[]): string {
  const [firstX, firstY] = top[0] ?? [0, 0];
  const [lastX, lastY] = bottom.at(-1) ?? top.at(-1) ?? [0, 0];
  return `M${firstX},${firstY}${topSegments.join("")}L${lastX},${lastY}${bottomSegments.join("")}Z`;
}

export const smoothCurve: ChartCurve = {
  line(points) {
    if (points.length === 0) return "";
    const [x, y] = points[0] ?? [0, 0];
    return `M${x},${y}${monotoneSegments(points).join("")}`;
  },
  area(top, bottom) {
    if (top.length === 0) return "";
    return closedArea(top, bottom, monotoneSegments(top), reversedMonotoneSegments(bottom));
  },
};

function stepSegments(points: readonly Point[]): string[] {
  return points.slice(1).map(([x, y]) => `H${x}V${y}`);
}

function reversedStepSegments(points: readonly Point[]): string[] {
  return points
    .slice(0, -1)
    .map(([, y], index) => `V${y}H${points[index]?.[0] ?? 0}`)
    .reverse();
}

export const stepCurve: ChartCurve = {
  line(points) {
    if (points.length === 0) return "";
    const [x, y] = points[0] ?? [0, 0];
    return `M${x},${y}${stepSegments(points).join("")}`;
  },
  area(top, bottom) {
    if (top.length === 0) return "";
    return closedArea(top, bottom, stepSegments(top), reversedStepSegments(bottom));
  },
};

export function chartCurve(name: ChartCurveName): ChartCurve | undefined {
  if (name === "smooth") return smoothCurve;
  if (name === "step") return stepCurve;
  return undefined;
}

import {
  type ChartLinearGradient,
  type ChartTooltipContentContext,
  type MarkRenderContext,
  ruleX,
  ruleY,
  type SceneNode,
  text,
} from "@tanstack/charts";
import { decorative } from "@tanstack/charts/mark/decorative";
import { tooltip } from "@tanstack/charts/tooltip";
import { type ChartColor, chartColor } from "@/components/control-ui/ui/chart-colors";
import type { ChartFill, ChartSeriesRow, ChartXValue } from "@/components/control-ui/ui/chart-series";

type AnyChartMark = Parameters<typeof decorative>[0];

export type ChartPart = "area" | "area-hatched" | "line" | "dot" | "reference";

type SceneNodesTransform = (nodes: readonly SceneNode[], renderContext: MarkRenderContext) => SceneNode[];

function withSceneNodes<TMark extends AnyChartMark>(mark: TMark, transform: SceneNodesTransform): TMark {
  return {
    ...mark,
    initialize(context) {
      const initialized = mark.initialize(context);
      const { resolveLayout } = initialized;
      return {
        ...initialized,
        render: (renderContext) => {
          const scene = initialized.render(renderContext);
          return { ...scene, nodes: transform(scene.nodes, renderContext) };
        },
        resolveLayout: resolveLayout
          ? (layoutContext) => {
              const layout = resolveLayout(layoutContext);
              return {
                ...layout,
                render: (renderContext) => {
                  const scene = layout.render(renderContext);
                  return { ...scene, nodes: transform(scene.nodes, renderContext) };
                },
              };
            }
          : undefined,
      };
    },
  };
}

function withClass<TNode extends SceneNode>(node: TNode, className: string): TNode {
  return { ...node, className: node.className ? `${node.className} ${className}` : className };
}

export function chartPart<TMark extends AnyChartMark>(mark: TMark, ...parts: ChartPart[]): TMark {
  const partClass = parts.map((part) => `cui-chart-${part}`).join(" ");
  return withSceneNodes(mark, (nodes) => nodes.map((node) => withClass(node, partClass)));
}

const BASELINE_TOLERANCE = 0.5;

function withNegativeBars(nodes: readonly SceneNode[], axis: "x" | "y", baseline: number): SceneNode[] {
  return nodes.map((node) => {
    if (node.kind === "group") return { ...node, children: withNegativeBars(node.children, axis, baseline) };
    if (node.kind !== "rect") return node;
    const negative = axis === "y" ? node.y >= baseline - BASELINE_TOLERANCE : node.x + node.width <= baseline + BASELINE_TOLERANCE;
    return negative ? withClass(node, "cui-chart-bar-negative") : node;
  });
}

export function chartBars<TMark extends AnyChartMark>(mark: TMark, axis: "x" | "y"): TMark {
  return withSceneNodes(mark, (nodes, renderContext) => {
    const valueScale = renderContext.scales[axis];
    const tagged = valueScale ? withNegativeBars(nodes, axis, valueScale.map(0)) : [...nodes];
    return tagged.map((node) => withClass(node, `cui-chart-bar-${axis}`));
  });
}

export type ChartGradientKind = "area" | "bar-y" | "bar-y-negative" | "bar-x" | "bar-x-negative" | "arc";

type GradientStop = [offset: number, opacity: number, lightnessLift?: number];

const BAR_STOPS: GradientStop[] = [
  [0, 1],
  [1, 0.55],
];

const GRADIENT_GEOMETRY: Record<ChartGradientKind, Omit<ChartLinearGradient, "id" | "stops"> & { stops: GradientStop[] }> = {
  area: {
    x1: 0,
    y1: 0,
    x2: 0,
    y2: 1,
    stops: [
      [0, 0.5],
      [0.6, 0.12],
      [1, 0],
    ],
  },
  "bar-y": { x1: 0, y1: 0, x2: 0, y2: 1, stops: BAR_STOPS },
  "bar-y-negative": { x1: 0, y1: 1, x2: 0, y2: 0, stops: BAR_STOPS },
  "bar-x": { x1: 1, y1: 0, x2: 0, y2: 0, stops: BAR_STOPS },
  "bar-x-negative": { x1: 0, y1: 0, x2: 1, y2: 0, stops: BAR_STOPS },
  arc: {
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    stops: [
      [0, 1],
      [1, 1, 0.1],
    ],
  },
};

export function chartGradient(color: ChartColor, kind: ChartGradientKind): ChartLinearGradient {
  const { stops, ...geometry } = GRADIENT_GEOMETRY[kind];
  return {
    ...geometry,
    id: `cui-${kind}-${color}`,
    stops: stops.map(([offset, opacity, lightnessLift]) => ({
      offset,
      opacity,
      color: lightnessLift ? `oklch(from ${chartColor(color)} calc(l + ${lightnessLift}) c h)` : chartColor(color),
    })),
  };
}

export function chartGradients(colors: Iterable<ChartColor>, kind: ChartGradientKind): ChartLinearGradient[] {
  return [...new Set(colors)].map((color) => chartGradient(color, kind));
}

export function chartHatch(color: ChartColor): string {
  return `var(--_cui-chart-hatch-${color}, ${chartColor(color)})`;
}

export function chartFillPaint(color: ChartColor, fill: ChartFill, kind: ChartGradientKind): string {
  if (fill === "gradient") return `url(#cui-${kind}-${color})`;
  if (fill === "hatched") return chartHatch(color);
  return kind === "area" ? `oklch(from ${chartColor(color)} l c h / 0.2)` : chartColor(color);
}

type ChartBarPaintRow = { color: ChartColor; fill: ChartFill; value: number | null };

function barGradientKind(axis: "x" | "y", value: number | null): ChartGradientKind {
  return value !== null && value < 0 ? `bar-${axis}-negative` : `bar-${axis}`;
}

export function chartBarFill(row: ChartBarPaintRow, axis: "x" | "y"): string {
  return chartFillPaint(row.color, row.fill, barGradientKind(axis, row.value));
}

export function chartBarGradients(rows: readonly ChartBarPaintRow[], axis: "x" | "y"): ChartLinearGradient[] {
  const gradients = new Map<string, ChartLinearGradient>();
  for (const row of rows) {
    if (row.fill !== "gradient") continue;
    const gradient = chartGradient(row.color, barGradientKind(axis, row.value));
    gradients.set(gradient.id, gradient);
  }
  return [...gradients.values()];
}

export function chartOutline(color: ChartColor, fill: ChartFill): string {
  return fill === "hatched" ? chartColor(color) : "none";
}

export function quietAxis<TValue>(format: (value: TValue) => string) {
  return { line: false, ticks: { line: false, padding: 8, format } } as const;
}

export const quietGrid = { strokeDasharray: "3 3" } as const;

export const dimUnfocused = [{ when: { focus: "unmatched" }, style: { opacity: 0.4 } }] as const;

export type ChartReference = { value: number; label?: string; color?: ChartColor };

export function chartReferenceMarks(references: readonly ChartReference[], axis: "x" | "y", anchor: ChartXValue | undefined) {
  if (references.length === 0) return [];
  const paint = {
    strokeDasharray: "4 4",
    strokeOpacity: 0.7,
    stroke: (reference: ChartReference) => chartColor(reference.color ?? "neutral"),
  };
  const labelled = references.filter((reference) => reference.label);
  const labelPaint = {
    text: "label",
    fill: (reference: ChartReference) => chartColor(reference.color ?? "neutral"),
    fontSize: 11,
  } as const;
  const rules = axis === "y" ? ruleY(references, { y: "value", ...paint }) : ruleX(references, { x: "value", ...paint });
  const marks = [decorative(chartPart(rules, "reference"))];
  if (labelled.length === 0 || anchor === undefined) return marks;
  const labels =
    axis === "y"
      ? text(labelled, { ...labelPaint, x: () => anchor, y: "value", anchor: "end", dy: -6 })
      : text(labelled, { ...labelPaint, x: "value", y: () => anchor, anchor: "start", dx: 6 });
  return [...marks, decorative(labels)];
}

type SeriesPoint = { key: string; datum: ChartSeriesRow };

export function seriesTooltip(
  seriesLabels: readonly string[],
  formatX: (value: ChartXValue) => string,
  formatValue: (value: number) => string,
) {
  const seriesRank = (point: SeriesPoint) => seriesLabels.indexOf(point.datum.series);
  return {
    use: tooltip,
    content: (points: readonly SeriesPoint[], context: ChartTooltipContentContext) => ({
      title: points[0] ? formatX(points[0].datum.x) : undefined,
      rows: [...points]
        .sort((left, right) => seriesRank(left) - seriesRank(right))
        .flatMap((point) =>
          point.datum.value === null
            ? []
            : {
                label: point.datum.series,
                value: formatValue(point.datum.value),
                color: chartColor(point.datum.color),
                active: point.key === context.primaryPoint?.key,
              },
        ),
    }),
  };
}

import { defineChart } from "@tanstack/charts";
import { decorative } from "@tanstack/charts/mark/decorative";
import { pie, polar, radialArc, radialBarAngle } from "@tanstack/charts/polar";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { tooltip } from "@tanstack/charts/tooltip";
import { type ChartColor, chartColor, chartSeriesColor } from "@/components/control-ui/ui/chart-colors";
import { chartFillPaint, chartGradients, chartHatch, chartOutline, dimUnfocused } from "@/components/control-ui/ui/chart-marks";
import { type ChartFill, type ChartValueKey, type ChartXKey, chartFormatters } from "@/components/control-ui/ui/chart-series";

export type ChartSliceOptions<TDatum> = {
  data: readonly TDatum[];
  label: ChartXKey<TDatum>;
  value: ChartValueKey<TDatum>;
  colors?: Partial<Record<string, ChartColor>>;
  fill?: ChartFill;
  fills?: Partial<Record<string, ChartFill>>;
  formatValue?: (value: number) => string;
  locale?: Intl.LocalesArgument;
};

export type ChartSlice = { id: string; label: string; value: number; color: ChartColor; fill: ChartFill };

export function resolveChartSlices<TDatum>(options: ChartSliceOptions<TDatum>): ChartSlice[] {
  return options.data.flatMap((datum, index) => {
    const label: unknown = datum[options.label];
    const value: unknown = datum[options.value];
    if (typeof label !== "string" || typeof value !== "number" || !Number.isFinite(value) || value < 0) return [];
    return {
      id: label,
      label,
      value,
      color: options.colors?.[label] ?? chartSeriesColor(index),
      fill: options.fills?.[label] ?? options.fill ?? "gradient",
    };
  });
}

export type DonutChartOptions<TDatum> = ChartSliceOptions<TDatum> & { innerRadius?: number };

export function donutChart<TDatum>(options: DonutChartOptions<TDatum>) {
  const slices = resolveChartSlices(options);
  const innerRadius = options.innerRadius ?? 0.62;
  const formats = chartFormatters(options.locale);
  const formatValue = options.formatValue ?? formats.value;
  return defineChart({
    marks: [
      polar({
        marks: [
          radialArc(pie(slices, { value: "value", gapAngle: 0.025 }), {
            key: "label",
            innerRadius: ({ radius }) => radius * innerRadius,
            cornerRadius: 4,
            fill: (slice) => chartFillPaint(slice.color, slice.fill, "arc"),
            stroke: (slice) => chartOutline(slice.color, slice.fill),
            strokeWidth: 1,
            className: "cui-chart-arc",
            states: dimUnfocused,
          }),
        ],
        scales: { angle: null, radius: null },
        inset: 4,
      }),
    ],
    scales: { x: null, y: null },
    gradients: chartGradients(
      slices.filter((slice) => slice.fill === "gradient").map((slice) => slice.color),
      "arc",
    ),
    tooltip: {
      use: tooltip,
      content: (points, context) => ({
        rows: points.map((point) => ({
          label: point.datum.label,
          value: `${formatValue(point.datum.value)} · ${formats.percent(point.datum.fraction)}`,
          color: chartColor(point.datum.color),
          active: point.key === context.primaryPoint?.key,
        })),
      }),
    },
  });
}

export type RadialBarChartOptions<TDatum> = ChartSliceOptions<TDatum> & {
  max?: number;
  track?: "hatched" | "solid" | "none";
};

export function radialBarChart<TDatum>(options: RadialBarChartOptions<TDatum>) {
  const rows = resolveChartSlices(options);
  const max = options.max ?? Math.max(1, ...rows.map((row) => row.value));
  const track = options.track ?? "hatched";
  const formatValue = options.formatValue ?? chartFormatters(options.locale).value;
  const ringScales = () => ({
    angle: { scale: scaleLinear().domain([0, max]) },
    radius: {
      scale: () => scaleBand().padding(0.3),
      range: [({ radius }: { radius: number }) => radius * 0.4, ({ radius }: { radius: number }) => radius] as const,
    },
  });
  const trackMarks =
    track === "none"
      ? []
      : [
          decorative(
            polar({
              className: "cui-chart-radial-track",
              marks: [
                radialBarAngle(rows, {
                  id: "track",
                  key: "id",
                  radius: "label",
                  angle: () => max,
                  cornerRadius: "full",
                  fill: track === "hatched" ? chartHatch("neutral") : "oklch(from var(--chart-neutral) l c h / 0.15)",
                }),
              ],
              scales: ringScales(),
            }),
          ),
        ];
  return defineChart({
    marks: [
      ...trackMarks,
      polar({
        marks: [
          radialBarAngle(rows, {
            id: "value",
            key: "id",
            radius: "label",
            angle: "value",
            cornerRadius: "full",
            fill: (row) => chartFillPaint(row.color, row.fill, "arc"),
            stroke: (row) => chartOutline(row.color, row.fill),
            strokeWidth: 1,
            className: "cui-chart-radial-bar",
            states: dimUnfocused,
          }),
        ],
        scales: ringScales(),
      }),
    ],
    scales: { x: null, y: null },
    gradients: chartGradients(
      rows.filter((row) => row.fill === "gradient").map((row) => row.color),
      "arc",
    ),
    tooltip: {
      use: tooltip,
      content: (points, context) => ({
        rows: points.map((point) => ({
          label: point.datum.label,
          value: `${formatValue(point.datum.value)} / ${formatValue(max)}`,
          color: chartColor(point.datum.color),
          active: point.key === context.primaryPoint?.key,
        })),
      }),
    },
  });
}

import type { ChartPositionScaleOptions } from "@tanstack/charts";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { scalePoint } from "@tanstack/charts/scales/point";
import { type ChartColor, chartSeriesColor } from "@/components/control-ui/ui/chart-colors";

export type ChartFill = "gradient" | "hatched" | "solid";

export type ChartXValue = string | number | Date;

export type ChartXKey<TDatum> = { [K in keyof TDatum]-?: TDatum[K] extends ChartXValue ? K : never }[keyof TDatum] & keyof TDatum & string;

export type ChartValueKey<TDatum> = {
  [K in keyof TDatum]-?: TDatum[K] extends number | null | undefined ? K : never;
}[keyof TDatum] &
  keyof TDatum &
  string;

export type ChartSeries<TDatum> = {
  key: ChartValueKey<TDatum>;
  label?: string;
  color?: ChartColor;
  fill?: ChartFill;
  dashed?: boolean;
};

export type ResolvedChartSeries<TDatum> = Required<ChartSeries<TDatum>>;

export type ChartSeriesRow = {
  id: string;
  x: ChartXValue;
  value: number | null;
  series: string;
  color: ChartColor;
  fill: ChartFill;
};

export function resolveChartSeries<TDatum>(
  series: readonly ChartSeries<TDatum>[],
  fill: ChartFill = "gradient",
): ResolvedChartSeries<TDatum>[] {
  return series.map((entry, index) => ({
    key: entry.key,
    label: entry.label ?? entry.key,
    color: entry.color ?? chartSeriesColor(index),
    fill: entry.fill ?? fill,
    dashed: entry.dashed ?? false,
  }));
}

function isChartXValue(value: unknown): value is ChartXValue {
  return typeof value === "string" || (typeof value === "number" && Number.isFinite(value)) || value instanceof Date;
}

export function chartSeriesRows<TDatum>(
  data: readonly TDatum[],
  x: ChartXKey<TDatum>,
  series: readonly ResolvedChartSeries<TDatum>[],
): ChartSeriesRow[] {
  return series.flatMap((entry) =>
    data.flatMap((datum) => {
      const xValue: unknown = datum[x];
      if (!isChartXValue(xValue)) return [];
      const value: unknown = datum[entry.key];
      return {
        id: `${entry.key}:${xValue instanceof Date ? xValue.toISOString() : String(xValue)}`,
        x: xValue,
        value: typeof value === "number" && Number.isFinite(value) ? value : null,
        series: entry.label,
        color: entry.color,
        fill: entry.fill,
      };
    }),
  );
}

export type ChartFormatters = {
  x: (value: ChartXValue) => string;
  value: (value: number) => string;
  tick: (value: number) => string;
  percent: (value: number) => string;
};

export function chartFormatters(locale: Intl.LocalesArgument = "en-US"): ChartFormatters {
  const plainNumber = new Intl.NumberFormat(locale);
  const compactNumber = new Intl.NumberFormat(locale, { notation: "compact" });
  const percentNumber = new Intl.NumberFormat(locale, { style: "percent" });
  const shortDay = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", timeZone: "UTC" });
  return {
    x: (value) => {
      if (value instanceof Date) return shortDay.format(value);
      if (typeof value === "number") return plainNumber.format(value);
      return value;
    },
    value: (value) => plainNumber.format(value),
    tick: (value) => compactNumber.format(value),
    percent: (value) => percentNumber.format(value),
  };
}

export function chartXScale(
  rows: readonly { x: ChartXValue }[],
  kind: "point" | "band",
  override?: Partial<ChartPositionScaleOptions>,
): ChartPositionScaleOptions {
  if (override?.scale) return { ...override, scale: override.scale };
  const first = rows[0]?.x;
  if (first instanceof Date) {
    throw new Error("Chart presets need an xScale for Date x values, for example { scale: scaleUtc } from d3-scale.");
  }
  if (typeof first === "number") return { scale: scaleLinear, nice: true, ...override };
  return { scale: kind === "band" ? () => scaleBand().padding(0.3) : scalePoint, ...override };
}

"use client";

import type { ChartTooltipContent, ChartValue } from "@tanstack/charts";
import {
  type ChartTooltipBodyRenderContext,
  Chart as TanStackChart,
  type ChartProps as TanStackChartProps,
} from "@tanstack/charts/react/tooltip";
import { type ComponentProps, type CSSProperties, type ReactNode, useEffect, useId, useRef } from "react";
import type { ChartKnobStyle } from "@/components/control-ui/knob-contracts/chart-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { readDurationMs } from "@/components/control-ui/lib/motion";
import { CHART_COLORS, type ChartColor, chartColor } from "@/components/control-ui/ui/chart-colors";
import type { ChartFill } from "@/components/control-ui/ui/chart-series";

const NON_ID_CHARACTERS = /[^\w-]/g;

type ChartStyle = CSSProperties & ChartKnobStyle;

export type ChartRootProps = Omit<ComponentProps<"div">, "style"> & { style?: ChartStyle };

export function Chart({ className, style, ...props }: ChartRootProps) {
  return <div data-control-ui="chart" data-control-family="chart" data-slot="root" className={cn(className)} style={style} {...props} />;
}

export type ChartPlotProps<TDatum, TXValue extends ChartValue = ChartValue, TYValue extends ChartValue = ChartValue> = Omit<
  TanStackChartProps<TDatum, TXValue, TYValue>,
  "style" | "className"
> & {
  className?: string;
  style?: ChartStyle;
  children?: ReactNode;
};

type ChartPatternStyle = Record<`--_cui-chart-hatch-${ChartColor}` | "--_cui-chart-fade", string>;

type ChartSwatchStyle = CSSProperties & { "--_cui-chart-swatch": string };

function chartPatternStyle(id: string): ChartPatternStyle {
  return {
    "--_cui-chart-hatch-blue": `url(#${id}-hatch-blue)`,
    "--_cui-chart-hatch-purple": `url(#${id}-hatch-purple)`,
    "--_cui-chart-hatch-pink": `url(#${id}-hatch-pink)`,
    "--_cui-chart-hatch-orange": `url(#${id}-hatch-orange)`,
    "--_cui-chart-hatch-green": `url(#${id}-hatch-green)`,
    "--_cui-chart-hatch-yellow": `url(#${id}-hatch-yellow)`,
    "--_cui-chart-hatch-red": `url(#${id}-hatch-red)`,
    "--_cui-chart-hatch-neutral": `url(#${id}-hatch-neutral)`,
    "--_cui-chart-fade": `url(#${id}-fade)`,
  };
}

function ChartPatterns({ id }: { id: string }) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="patterns"
      width="0"
      height="0"
      className="absolute size-0 overflow-hidden"
    >
      <defs>
        {CHART_COLORS.map((color) => (
          <pattern key={color} id={`${id}-hatch-${color}`} patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(45)">
            <rect
              data-control-ui="chart"
              data-control-family="chart"
              data-slot="hatch-tint"
              width="6"
              height="6"
              fill={chartColor(color)}
            />
            <rect
              data-control-ui="chart"
              data-control-family="chart"
              data-slot="hatch-stripe"
              width="2"
              height="6"
              fill={chartColor(color)}
            />
          </pattern>
        ))}
        <linearGradient id={`${id}-fade-gradient`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="oklch(1 0 0)" />
          <stop offset="1" stopColor="oklch(1 0 0)" stopOpacity="0.15" />
        </linearGradient>
        <mask id={`${id}-fade`} maskContentUnits="objectBoundingBox">
          <rect width="1" height="1" fill={`url(#${id}-fade-gradient)`} />
        </mask>
      </defs>
    </svg>
  );
}

function renderChartTooltipBody<TDatum, TXValue extends ChartValue, TYValue extends ChartValue>(
  context: ChartTooltipBodyRenderContext<TDatum, TXValue, TYValue>,
) {
  return <ChartTooltipBody content={context.content} />;
}

export function ChartPlot<TDatum, TXValue extends ChartValue = ChartValue, TYValue extends ChartValue = ChartValue>({
  className,
  style,
  children,
  ...props
}: ChartPlotProps<TDatum, TXValue, TYValue>) {
  const patternId = `cui-chart-${useId().replace(NON_ID_CHARACTERS, "")}`;
  const plotRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = plotRef.current;
    if (!node) return;
    let settleTimer: number | undefined;
    const observer = new ResizeObserver(() => {
      node.dataset.resizing = "";
      clearTimeout(settleTimer);
      settleTimer = window.setTimeout(
        () => {
          delete node.dataset.resizing;
        },
        readDurationMs(node, "--duration-fast"),
      );
    });
    observer.observe(node);
    return () => {
      observer.disconnect();
      clearTimeout(settleTimer);
    };
  }, []);

  useEffect(() => {
    const node = plotRef.current;
    if (!node) return;
    let enterTimer: number | undefined;
    const observer = new MutationObserver((records) => {
      const tooltipShown = records.some(
        (record) =>
          record.oldValue !== null &&
          record.target instanceof HTMLElement &&
          record.target.classList.contains("ts-chart-tooltip") &&
          !record.target.hidden,
      );
      if (!tooltipShown) return;
      node.dataset.tooltipEntering = "";
      clearTimeout(enterTimer);
      enterTimer = window.setTimeout(
        () => {
          delete node.dataset.tooltipEntering;
        },
        readDurationMs(node, "--duration-fast"),
      );
    });
    observer.observe(node, { subtree: true, attributeFilter: ["hidden"], attributeOldValue: true });
    return () => {
      observer.disconnect();
      clearTimeout(enterTimer);
    };
  }, []);

  return (
    <div
      ref={plotRef}
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="plot"
      data-focus-ring="within"
      className={cn(className)}
      style={{ ...chartPatternStyle(patternId), ...style }}
    >
      <ChartPatterns id={patternId} />
      <TanStackChart renderTooltipBody={renderChartTooltipBody} {...props} />
      {children}
    </div>
  );
}

export function ChartCenter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="center"
      className={cn("pointer-events-none absolute inset-0 grid place-content-center text-center", className)}
      {...props}
    />
  );
}

export function ChartLegend({ className, ...props }: ComponentProps<"ul">) {
  return (
    <ul
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="legend"
      className={cn("text-label text-muted-foreground", className)}
      {...props}
    />
  );
}

export type ChartLegendItemProps = Omit<ComponentProps<"li">, "color"> & {
  color: ChartColor;
  fill?: ChartFill;
  hidden?: boolean;
  onHiddenChange?: (hidden: boolean) => void;
};

function ChartSwatch({ color }: { color: string }) {
  const style: ChartSwatchStyle = { "--_cui-chart-swatch": color };
  return <span aria-hidden="true" data-control-ui="chart" data-control-family="chart" data-slot="swatch" style={style} />;
}

export function ChartLegendItem({
  color,
  fill = "solid",
  hidden = false,
  onHiddenChange,
  children,
  className,
  style,
  ...props
}: ChartLegendItemProps) {
  const legendStyle: ChartSwatchStyle = { "--_cui-chart-swatch": chartColor(color), ...style };
  const content = (
    <>
      <span aria-hidden="true" data-control-ui="chart" data-control-family="chart" data-slot="swatch" />
      {children}
    </>
  );
  return (
    <li
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="legend-item"
      data-fill={fill}
      data-hidden={hidden ? "true" : undefined}
      className={cn(className)}
      style={legendStyle}
      {...props}
    >
      {onHiddenChange ? (
        <button
          type="button"
          data-control-ui="chart"
          data-control-family="chart"
          data-slot="legend-toggle"
          aria-pressed={!hidden}
          onClick={() => onHiddenChange(!hidden)}
        >
          {content}
        </button>
      ) : (
        <span className="inline-flex items-center gap-1.5">{content}</span>
      )}
    </li>
  );
}

export type ChartTooltipBodyProps = Omit<ComponentProps<"div">, "content"> & { content: string | ChartTooltipContent };

export function ChartTooltipBody({ content, className, ...props }: ChartTooltipBodyProps) {
  return (
    <div
      data-control-ui="chart"
      data-control-family="chart"
      data-slot="tooltip"
      className={cn("grid min-w-32 gap-1.5", className)}
      {...props}
    >
      {typeof content === "string" ? (
        <p className="text-label">{content}</p>
      ) : (
        <>
          {content.title ? (
            <p data-control-ui="chart" data-control-family="chart" data-slot="tooltip-title" className="font-medium text-label">
              {content.title}
            </p>
          ) : null}
          {content.rows.map((row) => (
            <div
              key={row.label}
              data-control-ui="chart"
              data-control-family="chart"
              data-slot="tooltip-row"
              data-active={row.active ? "true" : undefined}
              className="flex items-center gap-2 text-label"
            >
              <ChartSwatch color={row.color ?? "currentColor"} />
              <span className={row.active ? undefined : "text-muted-foreground"}>{row.label}</span>
              <span className="ms-auto font-medium tabular-nums">{row.value}</span>
            </div>
          ))}
        </>
      )}
    </div>
  );
}
